actions.script:
const body=JSON.parse(definitionJson || '{}')
body.folder=definitionFolder || '';body.tags=String(definitionTags || '').split(',').map(tag=>tag.trim()).filter(Boolean)
// A mount's editor saves only its types (reportDefinitionTypes, set in the mounting screen's always-actions), and a mount
// that shares in its own screen keeps the saved definition's group: a posted group is not taken.
const type=definitionType || 'dashboard', mountTypes=ec.context.get('reportDefinitionTypes')
if (Array.isArray(mountTypes) && mountTypes.length && !mountTypes.includes(type)) throw new Error('This editor saves only '+mountTypes.join(', ')+' definitions')
let userGroupId=definitionUserGroupId || null
if (ec.context.get('reportLinks')?.share) {
    userGroupId=null
    if (definitionId) {
        ec.message.pushErrors()
        try{const found=ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId}).requireNewTransaction(true).call();if(!ec.message.hasError() && found && found.definition)userGroupId=found.definition.userGroupId || null}
        catch(error){ec.logger.info('Definition '+definitionId+' not read for its group: '+String(error))}
        finally{ec.message.clearErrors();ec.message.popErrors()}
    }
}
const definition = {id:definitionId,type,title:definitionTitle,body,version:parseInt(definitionVersion || '0',10),userGroupId}
savedDefinition = ec.service.sync().name('org.moqui.report.ReportServices.save#Definition').parameters({definition,note:note || ''}).call().definition
definitionId = savedDefinition.id

// a mount's editor copies only its types (as save)
const mountTypes=ec.context.get('reportDefinitionTypes')
if (Array.isArray(mountTypes) && mountTypes.length) {
    const source=ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId}).call().definition
    if (!mountTypes.includes(source.type)) throw new Error('This editor copies only '+mountTypes.join(', ')+' definitions')
}
savedDefinition = ec.service.sync().name('org.moqui.report.ReportServices.copy#Definition').parameters({definitionId,newDefinitionId:copyId,title:copyTitle}).call().definition
definitionId = savedDefinition.id

// The datasets the author may read (each dataset's own artifact), and the mount's links and types.
datasetOptions=ec.service.sync().name('org.moqui.report.ReportServices.list#Datasets').call().datasets || []
const mountLinks=ec.context.get('reportLinks')
const allTypes=['dashboard','panel','dataset','search','alert','report']
const mountTypes=ec.context.get('reportDefinitionTypes')
definitionTypeOptions=(Array.isArray(mountTypes) && mountTypes.length ? allTypes.filter(type=>mountTypes.includes(type)) : allTypes).map(type=>({type}))
if (!definitionId && !definitionTypeOptions.some(option=>option.type===definitionType)) definitionType=definitionTypeOptions[0].type
definitionOffers={import:!mountLinks || !!mountLinks.import,share:!mountLinks || !mountLinks.share,
    panelEditor:sri.buildUrl(mountLinks ? mountLinks.panel || '.' : '//apps/dashboards/Definition').path}
// a new panel starts on Tools' log dataset where the author reads it, else on the first dataset they may read
const firstDataset=(datasetOptions.find(dataset=>dataset.id==='otel_logs') || datasetOptions[0] || {id:'otel_logs'}).id
definition = definitionId ? ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId}).call().definition : {id:'',type:definitionType || 'dashboard',title:'',body:definitionType==='panel'?{title:'New panel',visualization:'table',queries:[{datasetId:firstDataset,mode:'documents'}]}:definitionType==='report'?{dashboards:[],orientation:'portrait',paper:'letter',layout:'grid',appendix:true}:{panels:{},layout:{type:'autoGrid'}},readOnly:false}
definitionType = definition.type; definitionTitle = definition.title; definitionVersion = definition.version || 0; definitionUserGroupId = definition.userGroupId || null
definitionJson = JSON.stringify(definition.body,null,2)
definitionFolder=definition.body.folder || '';definitionTags=(definition.body.tags || []).join(', ')
libraryPanels=ec.service.sync().name('org.moqui.report.ReportServices.list#Definitions').parameters({definitionType:'panel'}).call().definitions || []
dashboardOptions=ec.service.sync().name('org.moqui.report.ReportServices.list#Definitions').parameters({definitionType:'dashboard'}).call().definitions || []
usedIn=definitionId?ec.service.sync().name('org.moqui.report.ReportServices.find#DefinitionUses').parameters({definitionId}).call().usedIn || []:[]
versionDiff=''
if (definitionId && !definition.readOnly) {
    const diff=ec.service.sync().name('org.moqui.report.ReportServices.get#DefinitionDiff').parameters({definitionId,
        fromVersion:leftVersion==null || leftVersion===''?undefined:Number(leftVersion),toVersion:rightVersion==null || rightVersion===''?undefined:Number(rightVersion)}).call()
    versionDiff=JSON.stringify(diff.changes || [],null,2)
}
versionList = definitionId ? ec.service.sync().name('org.moqui.report.ReportServices.versions#Definition').parameters({definitionId}).call().versions : []
